     [('0.5×3–1×10 م', 'مقاسات المجرى والسجاد', '0.5×3–1×10 m', 'Sluice & carpet sizes'), ('8 ورقات', 'سجاد العشب الصناعي', '8-leaf', 'Artificial-turf carpet'), ('1 كجم/ساعة', 'طاقة الطبق', '1 kg/h', 'Gold pan capacity')],
